local setting_view = {}

ViewSetting.kWindowEx = 101
ViewSetting.kModalWindowEx = 102
ViewSetting.kFullScreenWindowEx = 103
ViewSetting.kNormalViewEx = 111
ViewSetting.kModalViewEx = 112
ViewSetting.kFullScreenViewEx = 113

function ViewSetting:getViewConfig(view)
	return self._setting[view]
end

function ViewSetting:isFullScreen(view)
	local co = self._setting[view]

	if co then
		return co.showMode == ViewSetting.kFullScreenWindow or co.showMode == ViewSetting.kFullScreenView or co.showMode == ViewSetting.kFullScreenWindowEx or co.showMode == ViewSetting.kFullScreenViewEx
	end

	return false
end

function ViewSetting:isModal(view)
	local co = self._setting[view]

	if co then
		return co.showMode == ViewSetting.kModalWindow or co.showMode == ViewSetting.kModalView or co.showMode == ViewSetting.kModalWindowEx or co.showMode == ViewSetting.kModalViewEx
	end

	return false
end

function setting_view:init()
	self.isEditor = Framework.OSDef.isEditor

	self:initConfig()

	local views = CommonResPath.stillViews

	for i = 1, #views do
		local vName = views[i]

		if self[vName] then
			self[vName].autoDestroyTime = 1200
		end
	end

	local views2 = CommonResPath.frequentViews

	for i = 1, #views2 do
		local vName = views2[i]

		if self[vName] then
			self[vName].autoDestroyTime = -1
		end
	end
end

function setting_view:addConfig(viewName, presentor, showMode, extId, autoDestroyTime, syncOpenList, syncCloseList, supportBack)
	local clsPath = module_paths[presentor]

	if clsPath == nil then
		if Framework.OSDef.isEditor then
			printError(">>>>>>>> setting_view.lua 检测到空 presentor [[没提交代码或者已经被删除]] : ", presentor)
		end

		return
	end

	if Framework.OSDef.isEditor and viewName == nil then
		printError(">>>>>>>> setting_view.lua 检测到空 viewName [[没提交代码或者已经被删除]] : ", presentor)

		return
	end

	if not autoDestroyTime or autoDestroyTime <= 0 then
		autoDestroyTime = 20
	end

	if self[viewName] == nil then
		extId = extId or 0
		self[viewName] = {
			ViewName = viewName,
			presentor = presentor,
			showMode = showMode,
			extId = extId,
			autoDestroyTime = autoDestroyTime,
			syncOpenList = syncOpenList,
			syncCloseList = syncCloseList,
			supportBack = supportBack
		}
	else
		printError("Error: setting_view:addConfig  ViewName:" .. viewName .. " 配置已存在 ， 请重新检查")
	end
end

function setting_view:addShowName(ViewName, _showName)
	self:mergeConf(ViewName, {
		search_name = _showName
	})
end

function setting_view:mergeConf(ViewName, mergeList)
	if self[ViewName] == nil then
		self[ViewName] = {}
	end

	table.merge(self[ViewName], mergeList)
end

function setting_view:deleteConfig(ViewName)
	self[ViewName] = nil
end

